import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.DzNHXt93.js";const u=JSON.parse('{"title":"Form Proposal: VectorIndex","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/vector-index.md","filePath":"proposals/vector-index.md"}'),n={name:"proposals/vector-index.md"};function o(s,e,c,d,l,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="form-proposal-vectorindex" tabindex="-1">Form Proposal: VectorIndex <a class="header-anchor" href="#form-proposal-vectorindex" aria-label="Permalink to &quot;Form Proposal: VectorIndex&quot;">​</a></h1><p>Status: active Proposal; intended first v1alpha2 release <code>0.1.0</code>. A local candidate package exists under <code>forms/candidates/v1alpha2/</code>, but no released FormRef or public release identity exists yet.</p><h2 id="need-and-boundary" tabindex="-1">Need and boundary <a class="header-anchor" href="#need-and-boundary" aria-label="Permalink to &quot;Need and boundary&quot;">​</a></h2><p>Takosumi Cloud provides vector indexing. The candidate Form describes fixed dimension and metric compatibility, lifecycle identity, and a vector-index Interface. Engine, placement, capacity, replication, credentials, data plane, and price remain host-owned.</p><h2 id="substrate-neutrality-review" tabindex="-1">Substrate-neutrality review <a class="header-anchor" href="#substrate-neutrality-review" aria-label="Permalink to &quot;Substrate-neutrality review&quot;">​</a></h2><p>Dimensions and similarity metric determine whether vectors and queries are semantically compatible across managed vector products, search engines, and self-hosted indexes. index size, shard count, region, replication, quantization, endpoint protocol, and pricing tier remain host/profile concerns.</p><h2 id="lifecycle-and-security-risks" tabindex="-1">Lifecycle and security risks <a class="header-anchor" href="#lifecycle-and-security-risks" aria-label="Permalink to &quot;Lifecycle and security risks&quot;">​</a></h2><p>Dimension or incompatible metric changes require rebuild or replacement. Delete/rebuild can discard indexed vectors unless export/recovery exists. Import requires exact dimension, metric, namespace, and ownership evidence. Vectors, metadata, endpoints, and credentials never enter portable state.</p><h2 id="prior-art-and-gap" tabindex="-1">Prior art and gap <a class="header-anchor" href="#prior-art-and-gap" aria-label="Permalink to &quot;Prior art and gap&quot;">​</a></h2><p>OCCI generic Resource/Link, TOSCA data-service capabilities, managed vector database operators/Crossplane resources, and Terraform Pinecone/search/ Vectorize resources are applicable; CIMI has no vector-search contract. The gap is a minimal engine-neutral compatibility contract without owning scaling, credential, or commercial behavior.</p>',10)])])}const h=a(n,[["render",o]]);export{u as __pageData,h as default};
